/* @lc app=leetcode id=1870 lang=kotlin */ class Solution { fun minSpeedOnTime(dist: IntArray, hour: Double): Int = if (dist.size - 1 >= hour) -1 else generateSequence(1 to 10000000) { (low, high) -> if (low >= high) null else ((low + high) / 2).let { mid -> if (dist.indices.sumOf { i -> if (i == dist.lastIndex) dist[i].toDouble() / mid else kotlin.math.ceil(dist[i].toDouble() / mid) } <= hour) low to mid else (mid + 1) to high } }.last().first }